<?php
$copy=['title'=>'أرسل قصتك','desc'=>'لديك تجربة أو قصة غامضة؟ أرسلها إلى فريق سراديب للمراجعة.','email'=>'البريد الإلكتروني','phone'=>'الهاتف — اختياري','story_title'=>'عنوان القصة','story'=>'نص القصة','image'=>'صورة اختيارية','rights'=>'أؤكد أن لدي الحق في إرسال هذا المحتوى للنشر أو المراجعة.','send'=>'إرسال القصة']; if($locale!=='ar')foreach($copy as $k=>$v)$copy[$k]=translation_text('send_story',$k,$locale,$v); if(!empty($managedPage))$copy['title']=$managedPage['title'];
?>
<script>
document.addEventListener('DOMContentLoaded',function(){
  const form=document.getElementById('send-story-form');
  const category=form?.querySelector('[name="category_id"]')?.closest('label');
  if(!form||!category||form.querySelector('[name="original_locale"]')) return;
  const field=document.createElement('label');
  const select=document.createElement('select');
  select.name='original_locale'; select.required=true;
  const placeholder=document.createElement('option'); placeholder.value=''; placeholder.textContent='اختر لغة النص'; select.append(placeholder);
  const languages=<?=json_encode(array_map(static fn(string $code): array => ['code'=>$code,'name'=>language_name($code)],array_keys($writingLanguages??article_locales())),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
  const selected=<?=json_encode((string)(old('original_locale')?:$locale),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
  languages.forEach(function(language){const item=document.createElement('option');item.value=language.code;item.textContent=language.name;item.selected=language.code===selected;select.append(item);});
  field.append(document.createTextNode('لغة النص الأصلي'));
  field.append(select);
  category.parentNode.insertBefore(field,category);
});
</script>
<section class="page-hero send-story-hero"><div class="container"><span class="eyebrow">Saradeeeb</span><h1><?=e($copy['title'])?></h1><?=!empty($managedPage)?\App\Services\ManagedPages::body($managedPage):'<p>'.e($copy['desc']).'</p>'?></div></section>
<section class="send-story-rules" aria-labelledby="send-story-rules-title"><div class="container"><div class="send-story-rules-head"><span class="eyebrow">Saradeeeb</span><h2 id="send-story-rules-title">شروط النشر في سراديب</h2><p>نقرأ كل مشاركة بعناية، ونحافظ على معناها وروحها قبل اتخاذ قرار النشر.</p></div><div class="send-story-rules-grid"><article><h3>الأصالة والملكية الفكرية</h3><p>أرسل نصًا من تأليفك، أو تملك حق نشره، مع احترام حقوق المؤلفين والمصادر.</p></article><article><h3>وضوح الفكرة وجودة اللغة</h3><p>نرحب بالنصوص الواضحة والمنظمة، وبأسلوب عربي سليم يسهّل القراءة ويحفظ تسلسل الأفكار.</p></article><article><h3>احترام الآخرين</h3><p>نرفض الإساءة والتشهير وخطاب الكراهية والسخرية الجارحة، ونحترم كرامة الجميع.</p></article><article><h3>النقد المسؤول</h3><p>نرحب بالنقد الفكري والعلمي المبني على الحجة، ونفصل بين مناقشة الفكرة واحترام صاحبها.</p></article><article><h3>تحديد طبيعة المشاركة</h3><p>وضّح ما إذا كان النص تجربة شخصية، أو قصة خيالية، أو مقالًا تحليليًا.</p></article><article><h3>الخصوصية</h3><p>لا تنشر بيانات شخصية أو معلومات خاصة عن الآخرين من دون موافقة صريحة.</p></article><article><h3>المراجعة التحريرية</h3><p>تخضع المشاركات للمراجعة قبل النشر، وللإدارة حق طلب التعديل أو الاعتذار عن النشر وفق سياسة الموقع.</p></article><article class="send-story-values"><h3>قيم منتدى سراديب</h3><p>نؤمن بالمعرفة والحوار الهادئ، ونواجه الادعاءات بالدليل، ونقدّم اختلاف الأفكار باحترام.</p></article></div>
<section class="send-story-ethics" aria-labelledby="send-story-ethics-title"><h2 id="send-story-ethics-title">سموّ الكلمة والترفع عن الشخصنة</h2><p>ليست سراديب ساحةً للتشهير بالأشخاص، ولا منبرًا لتصفية الحسابات أو خوض المعارك الشخصية، مهما بلغت تفاهة ما يُقال أو استفزاز قائله.</p><p>وليس ترفّعنا عن المهاترات تقديرًا لمن يثيرها، ولا إقرارًا بما يطرحون، بل صونًا لمكانة سراديب وهيبة الكلمة وكرامة من يحمل رسالتها.</p><p>وأنت لست ضيفًا عابرًا هنا، بل جزءٌ أصيل من سراديب، ومن قدرها قدرك. فلا تمنح الخصومات من قلمك ما لا تستحق، ولا تجعل من الإساءة طريقًا للرد على الإساءة.</p><p>ناقش الفكرة، وفنّد الحجة، واختلف كما تشاء؛ لكن دع الأشخاص خارج ميدان الخصومة. فالكلمة الراقية تبقى، أما المهاترات فيطويها النسيان.</p></section>
<div class="send-story-poetry" role="note" aria-label="قصيدة سمو الكلمة"><div class="send-story-verse"><span>وصُنْ قلمك إن خطّ المعاني</span><span>فإن الحبر أسمى من السبابِ</span></div><div class="send-story-verse"><span>وجادل فكرهم بالحق حتى</span><span>يفرّ الزور من وجه الصوابِ</span></div></div></div></section>
<section class="section"><div class="container"><div class="panel public-form-card"><form id="send-story-form" method="post" enctype="multipart/form-data" action="<?=e(locale_url($locale,'send-story'))?>" class="form-grid"><?=csrf_field()?><input type="text" name="website" value="" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px" aria-hidden="true"><label>اسم الكاتب أو الاسم المستعار <span aria-hidden="true">*</span><input name="name" value="<?=old('name')?>" required minlength="2" maxlength="80" autocomplete="name" aria-describedby="author-name-help"><small id="author-name-help">اكتب الاسم الذي ترغب في ظهوره مع القصة.</small></label><label><?=e($copy['email'])?> <small>(اختياري)</small><input type="email" name="email" value="<?=old('email')?>" maxlength="190"></label><label><?=e($copy['phone'])?><input name="phone" value="<?=old('phone')?>" maxlength="60"></label><label>تصنيف المشاركة<select name="category_id" required><option value="">اختر التصنيف</option><?php foreach(($categories??[]) as $category):?><option value="<?=$category['id']?>"><?=e($category['name'])?></option><?php endforeach;?></select></label><label>نوع المشاركة<select name="submission_type" required><option value="experience">تجربة حقيقية</option><option value="fiction">قصة خيالية</option><option value="analysis">مقال تحليلي</option></select></label><label><?=e($copy['story_title'])?><input name="title" value="<?=old('title')?>" required minlength="4" maxlength="220"></label><label class="span-2"><?=e($copy['story'])?><textarea name="story" rows="16" required minlength="120" maxlength="100000"></textarea></label><label class="span-2"><?=e($copy['image'])?><input type="file" name="image" accept="image/png,image/jpeg,image/webp,image/avif"></label><label class="check span-2"><input type="checkbox" name="rights" value="1" required> <span><?=e($copy['rights'])?> أوافق على شروط النشر.</span></label><div class="span-2"><button class="btn btn-primary" type="submit"><?=e($copy['send'])?> للمراجعة</button></div></form></div><aside class="send-story-help" aria-labelledby="send-story-help-title"><h2 id="send-story-help-title">هل تواجه صعوبة في إرسال قصتك؟</h2><p>إذا واجهتك مشكلة أثناء كتابة قصتك أو إرسالها، فتواصل مع فريق سراديب وسنساعدك.</p><a class="btn btn-secondary" href="<?=e(locale_url($locale,'contact'))?>">تواصل معنا</a></aside></div></section><script>document.getElementById('send-story-form')?.addEventListener('submit',function(e){const n=this.elements.namedItem('name');if(!n)return;const v=n.value.trim().replace(/\s+/g,' ');n.value=v;if(v.length<2||v.length>80){n.setCustomValidity('اكتب اسم الكاتب أو الاسم المستعار من حرفين إلى 80 حرفًا.');e.preventDefault();n.reportValidity();}else n.setCustomValidity('');});</script>
